200	pub fn surfaceSize(self: *const Metal) !struct { width: u32, height: u32 } {
201	    const bounds = self.layer.layer.getProperty(graphics.Rect, "bounds");
202	    const scale = self.layer.layer.getProperty(f64, "contentsScale");
