209	            @as(u32, @intFromFloat(bounds.size.width * scale)),
210	            self.device.max_texture_size,
211	        ),
212	        .height = @min(
213	            @as(u32, @intFromFloat(bounds.size.height * scale)),
214	            self.device.max_texture_size,
215	        ),
216	    };
217	}
