    68	/// Warm up the Metal device machinery. The first Metal device query in
    69	/// a process takes multiple milliseconds; once warm, subsequent queries
    70	/// are effectively free. Calling this early (e.g. on a background
    71	/// thread at app startup; Metal device queries are thread-safe) moves
    72	/// that one-time cost off the critical path of the first surface's
    73	/// renderer initialization.
    74	pub fn warmup() void {
    75	    const device = chooseDevice() catch return;
    76	    defer device.release();
    77	
    78	    // Create and release a command queue. The first command queue
    79	    // created for a device pays additional one-time driver setup
    80	    // costs; subsequent creations are much cheaper.
    81	    const queue = device.msgSend(objc.Object, objc.sel("newCommandQueue"), .{});
    82	    queue.release();
    83	
    84	    // Build and discard our shader pipelines for both pixel formats we
    85	    // may use (which one is used depends on the blending config). The
    86	    // first pipeline state creation compiles shaders which is slow;
    87	    // once warm, later creations hit driver and OS caches.
    88	    inline for (.{
    89	        mtl.MTLPixelFormat.bgra8unorm_srgb,
    90	        mtl.MTLPixelFormat.bgra8unorm,
    91	    }) |format| {
    92	        if (shaders.Shaders.init(
    93	            std.heap.c_allocator,
    94	            device,
    95	            &.{},
    96	            format,
    97	        )) |s| {
    98	            var s_mut = s;
    99	            s_mut.deinit(std.heap.c_allocator);
   100	        } else |err| {
   101	            log.warn("metal warmup shader init failed err={}", .{err});
   102	        }
   103	    }
   104	}
