   138	/// Determines the maximum 2D texture size supported by the device.
   139	/// We need to clamp our frame size to this if it's larger.
   140	fn queryMaxTextureSize(device: objc.Object) u32 {
   141	    // https://developer.apple.com/metal/Metal-Feature-Set-Tables.pdf
   142	
   143	    if (device.msgSend(
   144	        bool,
   145	        objc.sel("supportsFamily:"),
   146	        .{mtl.MTLGPUFamily.apple10},
   147	    )) return 32768;
   148	
   149	    if (device.msgSend(
   150	        bool,
   151	        objc.sel("supportsFamily:"),
   152	        .{mtl.MTLGPUFamily.apple3},
   153	    )) return 16384;
   154	
   155	    return 8192;
   156	}
