   106	fn chooseDevice() error{NoMetalDevice}!objc.Object {
   107	    var chosen_device: ?objc.Object = null;
   108	
   109	    switch (comptime builtin.target.os.tag) {
   110	        .macos => {
   111	            const devices = objc.Object.fromId(mtl.MTLCopyAllDevices());
   112	            defer devices.release();
   113	
   114	            var iter = devices.iterate();
   115	            while (iter.next()) |device| {
   116	                // We want a GPU that’s connected to a display.
   117	                if (device.getProperty(bool, "isHeadless")) continue;
   118	                chosen_device = device;
   119	
   120	                // If the user has an eGPU plugged in, they probably want
   121	                // to use it. Otherwise, integrated GPUs are better for
   122	                // battery life and thermals.
   123	                if (device.getProperty(bool, "isRemovable") or
   124	                    device.getProperty(bool, "isLowPower")) break;
   125	            }
   126	        },
   127	
   128	        .ios => {
   129	            chosen_device = objc.Object.fromId(mtl.MTLCreateSystemDefaultDevice());
   130	        },
   131	        else => @compileError("unsupported target for Metal"),
   132	    }
   133	
   134	    const device = chosen_device orelse return error.NoMetalDevice;
   135	    return device.retain();
   136	}
