 139	/// Complete this render pass.
 140	/// This struct can no longer be used after calling this.
 141	pub fn complete(self: *const Self) void {
 142	    _ = self;
 143	    gl.flush();
 144	}
 319	/// This performs no caching, it is up to the caller to cache calls to this
 320	/// if they want. This will also not resize the atlas if it is full.
 321	///
 322	/// IMPORTANT: this renders by /glyph index/ and not by /codepoint/. The caller
 323	/// is expected to translate codepoints to glyph indexes in some way. The most
 324	/// trivial way to do this is to get the Face and call glyphIndex. If you're
 325	/// doing text shaping, the text shaping library (i.e. HarfBuzz) will automatically
 326	/// determine glyph indexes for a text run.
 327	pub fn renderGlyph(
 328	    self: *CodepointResolver,
 329	    alloc: Allocator,
 330	    atlas: *Atlas,
 331	    index: Collection.Index,
 332	    glyph_index: u32,
 333	    opts: RenderOptions,
 334	) !Glyph {
 335	    // Special-case fonts are rendered directly.
 336	    if (index.special()) |sp| switch (sp) {
 337	        .sprite => return try self.sprite.?.renderGlyph(
 338	            alloc,
 339	            atlas,
 340	            glyph_index,
 341	            opts,
 342	        ),
 343	    };
 344	
 345	    const face = try self.collection.getFace(index);
 346	    const glyph = try face.renderGlyph(alloc, atlas, glyph_index, opts);
 347	    // log.warn("GLYPH={}", .{glyph});
 348	    return glyph;
 349	}
