   131	    return .{
   132	        .framebuffer = fbo,
   133	        .texture = texture,
   134	        .export_framebuffer = export_fbo,
   135	        .export_texture = export_texture,
   136	        .width = opts.width,
   137	        .height = opts.height,
   138	    };
   139	}
